function cleanString(value) {
  if (value === undefined || value === null) return '';

  let text = String(value);

  // Remove broken UTF-16 surrogate characters
  text = text.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])/g, '');
  text = text.replace(/(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, '');

  // Force safe UTF-8 roundtrip
  text = Buffer.from(text, 'utf8').toString('utf8');

  return text;
}

function cleanValue(value) {
  if (Array.isArray(value)) return value.map(cleanValue);

  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([key, val]) => [key, cleanValue(val)])
    );
  }

  return cleanString(value);
}

return $input.all().map(item => {
  const j = cleanValue(item.json);

  const aiPromptText = cleanString(`
jobKey: ${j.link}
jobLink: ${j.link}
jobTitle: ${j.title}
standardizedTitle: ${j.standardizedTitle || ''}
companyName: ${j.companyName}
companyWebsite: ${j.companyWebsite}
companyLinkedinUrl: ${j.companyLinkedinUrl}
companyEmployeesCount: ${j.companyEmployeesCount}
companySlogan: ${j.companySlogan || ''}
companyIndustries: ${JSON.stringify(j.industries || [])}
companyDescription: ${(j.companyDescription || '').substring(0, 1000)}

location: ${j.location}
country: ${j.country || ''}
seniorityLevel: ${j.seniorityLevel}
employmentType: ${j.employmentType}
jobFunction: ${j.jobFunction}
workplaceTypes: ${JSON.stringify(j.workplaceTypes || [])}

jobDescription: ${(j.descriptionText || '').substring(0, 3000)}
`);

  return {
    json: {
      ...j,
      aiPromptText,
    },
  };
});

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const st = j.signal_type || '';

  // --- Company fields ---
  let companyName = j.companyName || '';
  let companyWebsite = j.companyWebsite || '';
  let companyLinkedinUrl = j.companyLinkedin || j.companyLinkedinUrl || '';
  const companyEmployeesCount = j.companyEmployeeCount || 0;
  const companyDescription = j.companyDescription || j.descriptionText || '';
  const country = j.companyCountry || j.country || '';
  const location = j.location || j.companyCountry || '';

  // --- Signal-specific mapping ---
  let acquiringCompanyName = '';
  let jobOpeningTitle = '';
  let link = '';
  let postedAt = '';
  let personFullName = '';
  let personJobTitle = '';
  let personLinkedinUrl = '';

  if (st === 'funding') {
    // signalId, roundType, amount, currency, announcedDate, sources
    jobOpeningTitle = (j.roundType || 'funding')
      + (j.amount ? ' - $' + (j.amount / 1000000).toFixed(1) + 'M' : '');
    postedAt = j.occurredAt || j.announcedDate || '';
    link = (j.sources && j.sources[0]) ? j.sources[0].url : '';

  } else if (st === 'job_change') {
    // personName, personLinkedinUrl, newRole, postContent, companyLinkedinUrl, sources
    personFullName = j.personName || '';
    personJobTitle = j.newRole || '';
    personLinkedinUrl = j.personLinkedinUrl || '';
    jobOpeningTitle = j.newRole || '';
    postedAt = j.occurredAt || j.discoveredAt || '';
    link = (j.sources && j.sources[0]) ? j.sources[0].url : (j.personLinkedinUrl || '');

  } else if (st === 'hiring') {
    // id, jobId, jobUrl, title, location, datePosted, seniorityLevel,
    // jobFunction, industries, numApplicants, descriptionText
    jobOpeningTitle = j.title || '';
    postedAt = j.datePosted || j.createdAt || '';
    link = j.jobUrl || '';

  } else if (st === 'acquisition') {
    // acquiringCompanyId, acquiringCompanyName, acquiringCompanySlug,
    // amount, currency, percentage, announcedDate, sources
    acquiringCompanyName = j.acquiringCompanyName || '';
    if (acquiringCompanyName) {
      const acquiredName = companyName;
      companyName = acquiringCompanyName;
      acquiringCompanyName = acquiredName;
    }
    jobOpeningTitle = 'Acquisition'
      + (j.amount ? ' - $' + (j.amount / 1000000).toFixed(1) + 'M' : '');
    postedAt = j.occurredAt || j.announcedDate || '';
    link = (j.sources && j.sources[0]) ? j.sources[0].url : '';
  }

  // Build unique id
  const id = j.signalId || j.id || ($execution.id + '-' + out.length);

  // Ensure LinkedIn URL is full
  let liUrl = companyLinkedinUrl;
  if (liUrl && !liUrl.startsWith('http')) {
    liUrl = 'https://' + liUrl;
  }

  out.push({json: {
    signal_type: st,
    id: id,
    companyName: companyName,
    companyWebsite: companyWebsite,
    companyLinkedinUrl: liUrl,
    companyEmployeesCount: Number(companyEmployeesCount) || 0,
    companyDescription: companyDescription,
    location: location,
    country: country,
    jobOpeningTitle: jobOpeningTitle,
    acquiringCompanyName: acquiringCompanyName,
    link: link,
    postedAt: postedAt,
    personFullName: personFullName,
    personJobTitle: personJobTitle,
    personLinkedinUrl: personLinkedinUrl,
    title: jobOpeningTitle,
  }});
}
return out;

