return $input.all().map((item, index) => {

  // 1. Get the original full SignalBase item from your Dataset/Apify node
  // CHANGE "Dataset Funding" to match your exact Apify/Dataset node name in n8n!
  const originalSignal = $items("Dataset Funding")[index].json;

  // 2. Extract AI classification output
  let aiOutput = item.json;

  // If OpenAI returned stringified markdown like ```json ... ```, clean and parse it
